mapper.select:
SELECT id,name,status,total_stock,issued_count,valid_start_at,valid_end_at,rule_json,version,created_at,updated_at
FROM coupon_template

    AND status=#{status}

ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.sql:
FROM coupon_instance i
JOIN coupon_template t ON t.id=i.coupon_template_id

    AND i.coupon_template_id=#{templateId}
    AND i.status=#{status}
    AND i.order_id=#{orderId}
    AND i.created_at>=#{createdFrom}
    AND i.created_at<=#{createdTo}

mapper.update:
UPDATE coupon_template
SET status=#{toStatus}, version=version + 1, updated_at=#{now}
WHERE id=#{templateId} AND status=#{fromStatus} AND version=#{expectedVersion}

UPDATE coupon_template
SET issued_count = issued_count + 1, updated_at=#{now}
WHERE id=#{templateId}
